const body = $input.first().json.body || $input.first().json;
const issue = body.issue || {};
const repo = (body.repository && body.repository.full_name) || '';
const action = body.action || '';
if (!['opened','edited','reopened'].includes(action) || !issue.number || !repo) {
  return [{json:{skip:true, reason:'not an issue opened/edited/reopened event or missing fields'}}];
}
const text = ((issue.title||'')+' '+(issue.body||'')).toLowerCase();
const stop = new Set('the a an and or of to in on for with is it this that be are was not no when i my we you can cant cannot how do does did from as at by if have has had but so than then them there their what which will would should could also just get got use using used'.split(' '));
const tokens = [...new Set(text.replace(/[^a-z0-9_\s-]/g,' ').split(/\s+/).filter(w=>w.length>2 && !stop.has(w)))];
const bodyText = (issue.body||'');
const hasRepro = /(steps to reproduce|reproduce|repro|expected|actual|\bversion\b|stack ?trace|error:|traceback)/i.test(bodyText);
const hasCommand = /```|\$ |npm |pip |python |node |curl /i.test(bodyText);
return [{json:{repo, number:issue.number, title:issue.title||'', body:bodyText, author:(issue.user&&issue.user.login)||'', url:issue.html_url||'', tokens, hasRepro, hasCommand,
  query: tokens.slice(0,6).join(' ')}}];

const me = $('Normalize issue').first().json;
const items = ($input.first().json.items || []).filter(i=>i.number!==me.number && !i.pull_request);
const tk = s => new Set((s||'').toLowerCase().replace(/[^a-z0-9_\s-]/g,' ').split(/\s+/).filter(w=>w.length>2));
const jac = (A,B)=>{ let n=0; for (const w of A) if (B.has(w)) n++; const u=new Set([...A,...B]).size||1; return n/u; };
const myAll = new Set(me.tokens), myTitle = tk(me.title);
const scored = items.map(i=>{
  const tAll = tk((i.title||'')+' '+(i.body||'')), tTitle = tk(i.title);
  const score = 0.6*jac(myTitle,tTitle) + 0.4*jac(myAll,tAll);
  return {number:i.number, title:i.title, url:i.html_url, state:i.state, score:Math.round(score*100)/100, shared:[...myAll].filter(w=>tAll.has(w)).slice(0,8)};
}).sort((a,b)=>b.score-a.score).slice(0,3);
return [{json:{...me, candidates:scored}}];

const d = $input.first().json;
const top = d.candidates[0];
const missing = [];
if (!d.hasRepro) missing.push('reproduction steps / expected vs actual / version');
if (!d.hasCommand) missing.push('the exact failing command or code');
let rec, conf;
if (top && top.score >= 0.3) { rec = 'Possible duplicate of #'+top.number+'. Ask the reporter to confirm and link it before closing.'; conf = top.score>=0.5?'medium':'low'; }
else if (missing.length) { rec = 'Request missing details before labeling: '+missing.join('; ')+'.'; conf='medium'; }
else { rec = 'No close match found. Label for maintainer review.'; conf='low'; }
const draft = missing.length ? 'Thanks for the report! Could you add '+missing.join(' and ')+'? That will help us reproduce it.' : (top&&top.score>=0.3 ? 'Thanks! This looks related to #'+top.number+'. Does that cover your case?' : 'Thanks for the report, a maintainer will take a look.');
return [{json:{status:'needs_human_review', issue:{repo:d.repo, number:d.number, title:d.title, url:d.url}, recommendation:rec, confidence:conf, evidence:d.candidates, missing_details:missing, suggested_reply:draft, note:'Heuristic card: keyword-overlap ranking, no LLM. Nothing is posted to GitHub; write-back after approval is not built yet.'}}];
